(()=>{
 const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),won=v=>Number(v||0).toLocaleString('ko-KR')+'원',today=()=>new Date(Date.now()+9*3600000).toISOString().slice(0,10);
 window.shopPolicy={shippingFee:3000,freeShippingThreshold:30000,dispatchDays:'결제 후 1–2영업일'};window.currentCoupon='';
 window.shopShipping=subtotal=>subtotal>=window.shopPolicy.freeShippingThreshold?0:window.shopPolicy.shippingFee;
 window.availableCoupons=()=>{if(!window.moodnoteUser)return [];const used=new Set((window.moodnoteCouponUsage||[]).filter(u=>['reserved','used'].includes(u.status)).map(u=>u.code)),ordered=(window.moodnoteOrders||[]).some(o=>['결제 완료','배송 준비','배송 중','배송 완료','승인 확인 중'].includes(o.status));return (window.moodnoteCoupons||[]).filter(c=>c.enabled&&(!c.startDate||today()>=c.startDate)&&(!c.endDate||today()<=c.endDate)&&!used.has(c.code)&&(!c.firstOrder||!ordered));};
 window.shopDiscount=subtotal=>{const c=window.availableCoupons().find(c=>c.code===window.currentCoupon);if(!c||subtotal<c.minSpend)return 0;return Math.max(0,Math.min(subtotal,c.type==='percent'?Math.floor(subtotal*c.value/100):c.value,c.maxDiscount||subtotal));};
 window.shopCouponField=()=>`<section><h2>쿠폰 할인</h2><label>사용할 쿠폰<select id="checkout-coupon"><option value="">쿠폰 선택 안 함</option>${window.availableCoupons().map(c=>`<option value="${esc(c.code)}"${c.code===window.currentCoupon?' selected':''}>${esc(c.name)} · ${c.type==='percent'?c.value+'%':won(c.value)} 할인 · ${won(c.minSpend)} 이상</option>`).join('')}</select></label><p class="delivery-note">${window.moodnoteUser?'한 주문에 쿠폰 1장을 사용할 수 있습니다.':'로그인하면 보유 쿠폰을 사용할 수 있어요.'}</p></section>`;
 window.renderShopCoupons=()=>{const el=document.getElementById('my-coupons');if(!el)return;const coupons=window.availableCoupons();el.innerHTML=`<div class="account-section-head"><h2>쿠폰함</h2><span>${coupons.length}개</span></div>${coupons.length?`<div class="shop-coupons">${coupons.map(c=>`<article><strong>${c.type==='percent'?c.value+'%':won(c.value)} 할인</strong><h3>${esc(c.name)}</h3><p>${won(c.minSpend)} 이상 구매${c.maxDiscount?' · 최대 '+won(c.maxDiscount):''}</p><p>${esc(c.endDate)}까지 · ${c.firstOrder?'첫 주문 전용':'계정당 1회'}</p></article>`).join('')}</div>`:`<div class="account-empty"><h3>${window.moodnoteUser?'사용할 수 있는 쿠폰이 없어요':'로그인하면 쿠폰을 확인할 수 있어요'}</h3></div>`}`;};
 function totals(){const form=document.getElementById('checkout-form');if(!form||typeof cartSummary!=='function')return;const s=cartSummary();form.querySelector('.price-lines').innerHTML=`<p><span>상품 금액</span><b>${won(s.subtotal)}</b></p><p><span>배송비</span><b>${s.shipping?won(s.shipping):'무료'}</b></p><p><span>쿠폰 할인</span><b>−${won(s.discount)}</b></p><p class="grand-total"><span>최종 결제 금액</span><strong>${won(s.total)}</strong></p>`;const button=form.querySelector('[type="submit"]');if(!button.disabled){button.dataset.label=won(s.total)+' 토스로 결제하기';button.textContent=button.dataset.label;}}
 window.addEventListener('moodnote-coupons',()=>{window.renderShopCoupons();const select=document.getElementById('checkout-coupon');if(select){if(!window.availableCoupons().some(c=>c.code===window.currentCoupon))window.currentCoupon='';select.innerHTML='<option value="">쿠폰 선택 안 함</option>'+window.availableCoupons().map(c=>`<option value="${esc(c.code)}"${c.code===window.currentCoupon?' selected':''}>${esc(c.name)} · ${c.type==='percent'?c.value+'%':won(c.value)} 할인</option>`).join('');totals();}});
 window.addEventListener('moodnote-orders',()=>window.dispatchEvent(new Event('moodnote-coupons')));
 window.addEventListener('moodnote-auth-change',()=>{window.currentCoupon='';window.dispatchEvent(new Event('moodnote-coupons'));});
 window.addEventListener('moodnote-settings',e=>{window.shopPolicy={...window.shopPolicy,...e.detail.settings};totals();const threshold=won(window.shopPolicy.freeShippingThreshold),fee=won(window.shopPolicy.shippingFee);document.querySelectorAll('[data-shipping-policy]').forEach(el=>el.textContent=threshold+' 이상 구매 시 무료 배송');const promo=document.querySelector('.promo-bar');if(promo)for(const node of promo.childNodes)if(node.nodeType===3&&node.textContent.includes('30,000'))node.textContent=node.textContent.replace('30,000원',threshold);const footer=document.querySelector('#footer');if(footer){footer.querySelectorAll('span').forEach(el=>{if(el.textContent.includes('무료 배송'))el.textContent=threshold+' 이상 구매 시 무료 배송';if(el.textContent.includes('평일 10:00'))el.textContent=window.shopPolicy.hours||el.textContent;});}const current=location.hash.match(/^#product\/(.+)$/);if(current&&typeof byId==='function'&&byId(current[1]))renderDetail(byId(current[1]));});
 document.addEventListener('change',e=>{if(e.target.id==='checkout-coupon'){window.currentCoupon=e.target.value;totals();}});
})();
